const C = { blue: '#00a8ff', pink: '#ff1687', yellow: '#ffe600', green: '#00ff66', orange: '#ff4500', navy: '#15234c', gold: '#ffc928', cyan: '#41e6ff', purple: '#8b5cff', white: '#fff8e9' };
