import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const runtime='/home/runner/.local/share/omgithub-playwright';
const require=createRequire(`${runtime}/package.json`);
const { chromium }=require('playwright');
const config=JSON.parse(readFileSync(`${runtime}/linux.json`,'utf8'));
process.env.DISPLAY ||= ':'+readFileSync(`${runtime}/display`,'utf8').trim();
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:1440,height:900}});
page.on('response',r=>{if(r.status()>=400)console.log('HTTP',r.status(),r.url())});
await page.goto('http://127.0.0.1:5173');
await page.waitForTimeout(1000);
console.log('stats',await page.evaluate(()=>window.__renderStats?.()));
await page.locator('#play-button').click();
await page.waitForTimeout(5000);
console.log('stats-after',await page.evaluate(()=>window.__renderStats?.()));
await browser.close();

