files.patch:
Index: src/styles.css
===================================================================
--- src/styles.css
+++ src/styles.css
@@ -4,5 +4,5 @@
 @media(max-height:570px) and (min-width:701px){.start-card{padding:15px 32px}.game-logo{font-size:62px}.start-card p{margin:15px 0 8px}.start-facts{font-size:8px}.big-button{margin:12px auto}.start-controls{font-size:7px}}
 /* Keep the personalized race callout above the finish-screen overlay. */
 .checkpoint-banner{z-index:12;top:clamp(96px,14vh,130px);padding:10px 24px 11px;border-width:3px;background:linear-gradient(105deg,rgba(8,50,112,.97),rgba(83,28,139,.97) 55%,rgba(179,27,118,.97));box-shadow:0 6px 0 #172857,0 0 0 5px rgba(255,230,0,.2),0 12px 38px rgba(8,20,62,.55);font-weight:900;letter-spacing:.2px;line-height:1.15}
 .checkpoint-banner:before{font-size:10px;letter-spacing:2.4px}
-@media(max-width:700px){.checkpoint-banner{top:clamp(106px,16vh,132px);padding:12px 15px 13px;font-size:16px}}
+@media(max-width:700px){.checkpoint-banner{top:clamp(96px,14vh,120px);padding:8px 12px 9px;font-size:15px;line-height:1.1}}
